/// that runs to 40 rounds writes a file of up to a few hundred KB, and tabs and quotes make it about
/// 1.4 times that as JSON.
pub const MAX_BACKUP_FILE_CHARS: u64 = 524288;
/// The most damage that one hit reports, equal to `MAX_HEALTH`, so only overkill past that is
/// cut.
pub const MAX_DAMAGE: u64 = 1000;
/// Characters in the longest `reason` of a `player_disconnect`.
pub const MAX_DISCONNECT_REASON_CHARS: u64 = 64;
/// The most health or armor that a player can have, ten times the stock 100.
pub const MAX_HEALTH: u64 = 1000;
/// Characters in the longest `message` of a `log`.
pub const MAX_LOG_MESSAGE_CHARS: u64 = 8192;
/// Largest `memory_mb`, in MiB, far above what a game server uses.
pub const MAX_MEMORY_MB: u64 = 65536;
/// Characters in the longest player name. Steam allows 32, which UTF-16 writes in at most 64.
pub const MAX_PLAYER_NAME_CHARS: u64 = 64;
/// The highest port a slot may use, for its game port and its GOTV port.
pub const MAX_PORT: u64 = 65535;
/// Most stuck servers an `EventBacklog` lists, oldest first. Its counts include the rest. A
/// newer server is listed once older ones are uploaded.
pub const MAX_REPORTED_BACKLOGS: u64 = 100;
/// Most demos a `hello` lists. A node that keeps more lists its newest by
/// `modified_at`. An older demo is listed once newer ones are no longer on the node.
pub const MAX_REPORTED_DEMOS: u64 = 50;
/// The most rounds that `mp_maxrounds` can set for a match, ten times the stock 24. A launch that
/// asks for more fails validation.
pub const MAX_ROUNDS: u64 = 240;
/// The most shots that one player fires in a round, over all their weapons. It is about ten times
/// the most ammunition that a stock weapon carries, the Negev's 450. A
/// `round_shots` with more fails validation, so the plugin counts no more.
pub const MAX_ROUND_SHOTS: u64 = 4096;
/// Players that a CS2 server holds. The players and spectators of a roster fit in it together.
pub const MAX_SERVER_PLAYERS: u64 = 64;
/// Most slots a node may have, in `agent.yml`, `hello` and
/// `set_config`.
pub const MAX_SLOTS: u64 = 64;
/// Spectator slots on a CS2 server, for casters and anyone else who watches from the server.
pub const MAX_SPECTATORS: u64 = 2;
/// Characters in the longest team name.
pub const MAX_TEAM_NAME_LENGTH: u64 = 30;
/// Characters in the longest version string that `map_start` carries.
pub const MAX_VERSION_CHARS: u64 = 128;
/// Smallest `memory_mb`, in MiB. A game server uses about 700 MiB for a 1v1 and more for a full
/// match, so a lower cap would stop servers mid-match.
pub const MIN_MEMORY_MB: u64 = 1024;
/// Gigabytes of disk a node needs beyond its operating system: about 70 for the CS2 installation,
/// and the rest for an update to stage changed files in. A controller may warn about less.
pub const NODE_MIN_DISK_GB: u64 = 90;
/// The path the setup script `POST`s to for a node's `agent.yml`, with
/// `Authorization: Bearer <node token>`, `PROTOCOL_HEADER` and no body.
///
/// The answer is that node's `agent.yml` as `text/yaml`, and errors stay JSON. An unknown token is
/// refused with `401`. The file's `slots` may be empty, for slots that
/// `set_config` adds once the node connects.
///
/// The path is the setup script's default, `DEFAULT_SETUP_PATH` in the script. Operators can set
/// another with `--setup-path`.
pub const NODE_SETUP_PATH: &str = "/api/node/setup";
/// The shape of a node token. It has letters and digits only, so that it reads the same in a
/// header, a YAML file and a shell.
/// `/^[A-Za-z0-9]{32,128}$/`
#[allow(clippy::expect_used, reason = "a fixed pattern, which the tests compile")]
pub static NODE_TOKEN_PATTERN: LazyLock<Regex> = LazyLock::new(|| Regex::new("^[A-Za-z0-9]{32,128}$").expect("valid pattern"));
/// The environment variable the setup script reads the node token from instead of prompting for it.
pub const NODE_TOKEN_VARIABLE: &str = "ANKOR_NODE_TOKEN";
/// Why a node cannot run servers.
pub mod node_unavailable {
    /// The `MaintenanceOperation` in `operation` runs. It clears when the operation ends.
    pub const MAINTENANCE: &str = "maintenance";
    /// The agent cannot use the local store that keeps gameplay events until the controller takes
    /// them. `detail` says why.
    /// - If a call to the store waits past its limit, as on a disk that hangs, the code clears once
    ///   the store answers. Deleting the store or restarting the agent loses what waits to be written.
    /// - If the agent cannot open the store, such as one that a newer agent wrote, a corrupt file or
    ///   one it cannot write, the code lasts until a restart. Update the agent, or delete the store on
    ///   the host and restart the agent. Deleting it loses the events and server exits it keeps.
    pub const EVENT_STORAGE: &str = "event_storage";
    /// The disk under the agent's data directory has less than `DISK_SPACE_MIN_BYTES` free, too
    /// little for a match's events and demo. The agent asks the disk every 30 seconds and before each
    /// launch, so the code clears within 30 seconds of space being freed, and a launch that arrives
    /// sooner is taken if the disk has room by then.
    pub const DISK_SPACE: &str = "disk_space";
}
/// Longer reasons a node cannot run servers are cut to this many characters.
pub const NODE_UNAVAILABLE_DETAIL_MAX_CHARS: u64 = 512;
/// The repository of each official image. With `official_images_only` on, a node runs an image only
/// from its kind's repository, with any tag or digest, such as `ghcr.io/ankorcs/ankor-agent:0.8`.
pub mod official_images {
    pub const AGENT: &str = "ghcr.io/ankorcs/ankor-agent";
    pub const CS2: &str = "ghcr.io/ankorcs/ankor-cs2";
}
/// Longer os-release names are cut to this many characters.
pub const OS_NAME_MAX_CHARS: u64 = 256;
/// The header that carries `PROTOCOL_VERSION` on every request a node, its plugin or the setup
/// script makes.
pub const PROTOCOL_HEADER: &str = "Ankor-Protocol";
/// The wire's version: the `major.minor` of this package. Every request a node makes to the
/// controller, its demo uploads, the node-setup request and the plugin's connection to the agent
/// carry it in `PROTOCOL_HEADER`. A peer whose version is not compatible answers
/// `426 Upgrade Required`, and no frame is exchanged. [Versioning](/protocol/versioning/) says
/// which versions are.
pub const PROTOCOL_VERSION: &str = "0.10";
/// Seconds a server may keep running after its plugin sent `quitting`. Past them, the agent stops it
/// with `quit_timeout` as its `ServerExitReason`.
pub const QUIT_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(10);
/// The close code that goes with the reason `rate_limited`.
pub const RATE_LIMITED_CLOSE_CODE: u64 = 1008;
/// Allocations a node remembers, the most recently launched, and refuses to launch again with
/// `allocation_reused`. A controller that picks a fresh UUID for every launch never meets the
/// limit.
pub const REMEMBERED_ALLOCATIONS: u64 = 100;
/// Header names, in lower case, that a demo upload's configured header cannot take: the ones the
/// agent sets itself on every upload, and the ones that change how the request is framed.
pub const RESERVED_DEMO_HEADERS: &[&str] = &[
    "host",
    "content-type",
    "content-length",
    "transfer-encoding",
    "connection",
    "keep-alive",
    "upgrade",
    "expect",
    "te",
    "trailer",
    "ankor-protocol",
    "ankor-file-name",
    "ankor-match-id",
    "ankor-allocation-id",
];
/// Ticks that the agent holds and the controller shows per node, the newest last.
pub const RESOURCE_TICKS_HELD: u64 = 100;
/// Milliseconds between the agent's resource ticks, taken while it runs, watched or not.
pub const RESOURCE_TICK: std::time::Duration = std::time::Duration::from_secs(3);
/// Longest `detail` a server's exit carries. The agent cuts the message to it.
pub const SERVER_EXIT_DETAIL_MAX_CHARS: u64 = 512;
/// The agent keeps this many lines of each server's output and of each CS2 install or update's
/// output.
pub const SERVER_LOG_LINES: u64 = 2000;
/// Milliseconds the agent waits for the plugin to answer
/// `get_server_status`, `console_command`,
/// `restore_round` or `start_match`. Past it, the
/// request fails with `plugin_status_timeout`.
pub const SERVER_STATUS_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(10);
/// The path of the node-setup script, which a `GET` returns as the file. ankor.sh serves it for
/// every controller, which operators name with `--controller`.
pub const SETUP_SCRIPT_PATH: &str = "/node-setup.sh";
/// Where the setup script downloads itself from to re-run as root. It is `SETUP_SCRIPT_URL` in the
/// script.
pub const SETUP_SCRIPT_URL: &str = "https://ankor.sh/node-setup.sh";
/// Milliseconds a stopping agent waits for the requests it is running before it closes the socket,
/// counted from its `shutdown`. A request still running then is cut off.
pub const SHUTDOWN_REQUEST_WAIT: std::time::Duration = std::time::Duration::from_secs(5);
/// A slot id: 1 to 32 letters, digits, `_` or `-`. It becomes part of the game container's name.
/// `/^[A-Za-z0-9_-]{1,32}$/`
#[allow(clippy::expect_used, reason = "a fixed pattern, which the tests compile")]
pub static SLOT_ID_PATTERN: LazyLock<Regex> = LazyLock::new(|| Regex::new("^[A-Za-z0-9_-]{1,32}$").expect("valid pattern"));
/// Seconds a `reserve_slot` lasts, unless a `set_config`
/// with the slot's new token ends it first.
pub const SLOT_RESERVATION: std::time::Duration = std::time::Duration::from_mins(1);
/// Every close that the controller or the agent makes on purpose, with a code from
/// `CLOSE_CODES`. Any other code, or none, is a broken connection, and the agent redials.
// SOCKET_CLOSES is not generated: its value has no constant form.
/// Seconds a server may stay `starting` after its launch, or after a restarted agent took it over.
/// Past them, the agent stops it with `start_timeout` as its `ServerExitReason`.
pub const START_TIMEOUT: std::time::Duration = std::time::Duration::from_mins(1);
/// Seconds a stop's reply may take beyond its grace: Docker's answer to the stop, which the agent
/// waits for up to `DOCKER_ANSWER_TIMEOUT_MS`, and the reply.
pub const STOP_REPLY_MARGIN: std::time::Duration = std::time::Duration::from_secs(35);
/// Seconds of grace before `SIGKILL` for an ordinary stop.
pub const STOP_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(10);
/// Milliseconds a `watch_resources` or `watch_logs`
/// keeps its stream flowing. The next one resets it.
pub const WATCH_LEASE: std::time::Duration = std::time::Duration::from_mins(2);
